p.extended-example:
static int complain = 1;



int message_plugin_quit(WimpMessage *message, void *handle)

{

  if (message->data.words[0] != plugin_class)

    return 1; /* not for us */



  if (complain && modified)

  {

    /* Claim the message so that the quit is stopped for now */

    message->hdr.your_ref = message->hdr.my_ref;

    wimp_send_message(Wimp_EUserMessageAcknowledge, message,

                    message->hdr.sender, 0, NULL);



    /* Ask the user to Discard, Cancel or Set; for Cancel, abort */

    /* the quit for everyone, otherwise let the sender continue */

    ...

  }

  return 1;

}
